import assert from 'node:assert/strict';
import test from 'node:test';

import { permit } from './limit.mjs';

test('permit accepts Count values from 0 through 3 inclusive', () => {
  for (const count of [0, 1, 2, 3]) {
    assert.equal(permit(count), true, `${count} should be accepted`);
  }
});

test('permit rejects values outside the Count limit and non-integers', () => {
  for (const count of [-1, 4, 1.5, Number.NaN, '2']) {
    assert.equal(permit(count), false, `${String(count)} should be rejected`);
  }
});

